<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import {AlertCircle,ArrowRight,Check,CheckCircle2,Database,LoaderCircle,RefreshCw,Search,ShieldCheck,X} from 'lucide-vue-next';
import ApprovalReview from './ApprovalReview.vue';
import AppCreationRecovery from './AppCreationRecovery.vue';
import {createRequestGuard} from '../lib/async-response';
import {conversationReviewState} from '../lib/conversation-approvals';
type Item=Record<string,any>;
const props=defineProps<{tenant:string;tenantName:string;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[];project:[id:string];notice:[message:string];created:[resource:string]}>();
const name=ref('');const objective=ref('');const chosen=ref<string[]>([]);const tables=ref<Item[]>([]);const search=ref('');const tableStatus=ref<'idle'|'loading'|'ready'|'failed'>('idle');const tableError=ref('');
const busy=ref(false);const polling=ref(false);const uncertain=ref(false);const error=ref('');const review=ref<Item|null>(null);const project=ref<Item|null>(null);const prepared=ref<Item|null>(null);const clock=ref(Date.now());
const nameInput=ref<HTMLInputElement|null>(null);const reviewHeading=ref<HTMLElement|null>(null);const fieldId='create-app-'+crypto.randomUUID();const guard=createRequestGuard();let timer:ReturnType<typeof setInterval>|undefined;let notified=false;
const status=computed(()=>review.value?conversationReviewState(review.value,clock.value):'');
const running=computed(()=>['approved','executing'].includes(status.value));
const result=computed<Item>(()=>review.value?.payload?.execution?.result??{});
const confirmed=computed(()=>status.value==='completed'&&result.value.app_creation?.verified===true&&result.value.configuration_verified===true&&/^app:[1-9][0-9]*$/.test(result.value.resource??'')&&result.value.confirmed_name===prepared.value?.name&&project.value?.id===review.value?.project_id&&project.value?.source_ref===result.value.resource);
const filtered=computed(()=>tables.value.filter(item=>`${item.name} ${item.ref}`.toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR'))).slice(0,100));
const valid=computed(()=>name.value.trim().length>0&&name.value.trim().length<=100&&objective.value.length<=2000&&chosen.value.length<=8);
function accept(response:Item){
 const item=response.approval;if(!item||item.payload?.action?.action!=='create_app'||String(item.payload?.revision?.tenant_id)!==props.tenant||item.payload?.request_id!==prepared.value?.request_id||item.payload?.action?.name!==prepared.value?.name||(review.value&&item.id!==review.value.id)||!response.project||response.project.id!==item.project_id)throw new Error('A resposta não corresponde a esta criação. Consulte a operação em Atividade antes de continuar.');
 review.value=item;project.value=response.project;
}
async function loadTables(){
 if(tableStatus.value==='loading'||prepared.value)return;const current=guard.current();tableStatus.value='loading';tableError.value='';
 try{const response=await props.request(`/catalog/${props.tenant}/sections/table`);if(!current())return;if(String(response.tenant?.id)!==props.tenant||response.section!=='table'||response.capabilities?.table?.status!=='available'||!Array.isArray(response.resources?.table))throw new Error(response.capabilities?.table?.reason??'Não foi possível consultar as tabelas. Você pode começar sem vínculos e investigar as fontes no projeto.');tables.value=response.resources.table.filter((item:Item)=>/^table:[1-9][0-9]*$/.test(item.ref??''));tableStatus.value='ready';}
 catch(e){if(current()){tableStatus.value='failed';tableError.value=(e as Error).message;}}
}
async function prepare(){
 if(busy.value||(!prepared.value&&!valid.value))return;const current=guard.current();busy.value=true;error.value='';prepared.value??={request_id:crypto.randomUUID(),name:name.value.trim(),objective:objective.value.trim(),tables:[...chosen.value].sort()};
 try{const response=await props.request(`/catalog/${props.tenant}/apps/actions`,'POST',prepared.value);if(!current())return;accept(response);emit('updated');await nextTick();reviewHeading.value?.focus();}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())busy.value=false;}
}
function notify(){if(confirmed.value&&!notified){notified=true;emit('updated');emit('created',result.value.resource);emit('notice',result.value.message);}}
async function refreshStatus(force=false){
 if(polling.value||!review.value||(!force&&!running.value&&!uncertain.value))return;const current=guard.current();const id=review.value.id;polling.value=true;
 try{const response=await props.request(`/bi-actions/${id}`);if(!current()||review.value?.id!==id)return;accept(response);uncertain.value=false;error.value='';notify();}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())polling.value=false;}
}
async function decide(decision:'approved'|'rejected'){
 if(busy.value||status.value!=='pending'||uncertain.value||!review.value)return;const current=guard.current();const id=review.value.id;busy.value=true;error.value='';
 try{const response=await props.request(`/approvals/${id}/decide`,'POST',{decision,fingerprint:review.value.fingerprint});if(!current())return;if(response.id!==id||response.payload?.action?.action!=='create_app')throw new Error('A decisão ainda não foi confirmada. Consulte esta solicitação.');review.value=response;emit('updated');if(decision==='approved')await refreshStatus(true);}
 catch(e){if(current()){uncertain.value=true;error.value=(e as Error).message;}}finally{if(current())busy.value=false;}
}
function recovered(response:Item){accept(response);notify();}
onMounted(async()=>{await nextTick();nameInput.value?.focus();timer=setInterval(()=>{clock.value=Date.now();if(!document.hidden)refreshStatus();},2200);});
onUnmounted(()=>{guard.invalidate();if(timer)clearInterval(timer);});
</script>
<template><div class="app-creation-form">
 <template v-if="!review"><form @submit.prevent="prepare"><fieldset :disabled="busy||!!prepared"><legend class="sr-only">Dados da nova aplicação</legend><label :for="fieldId+'-name'">Como sua aplicação vai se chamar?</label><input :id="fieldId+'-name'" ref="nameInput" v-model="name" required maxlength="100" placeholder="Ex.: Visão financeira"><label :for="fieldId+'-objective'">O que você quer acompanhar? <small>Opcional</small></label><textarea :id="fieldId+'-objective'" v-model="objective" maxlength="2000" rows="3" placeholder="Ex.: Receitas, despesas e resultado por mês. A IA usará este objetivo quando você continuar no projeto."></textarea><section class="app-source-choice"><div><Database :size="19"/><div><strong>Escolha os dados quando estiver pronto</strong><p>Você pode começar sem tabelas e pedir à IA para investigar as fontes no projeto. Se já conhece suas tabelas, vincule até oito agora.</p></div></div><button v-if="tableStatus==='idle'||tableStatus==='failed'" type="button" class="secondary-button" @click="loadTables">{{tableStatus==='failed'?'Tentar consultar tabelas novamente':'Escolher tabelas agora'}}</button><p v-if="tableStatus==='loading'" role="status"><LoaderCircle :size="16" class="spin"/>Consultando suas tabelas…</p><template v-if="tableStatus==='ready'"><label :for="fieldId+'-search'">Buscar uma tabela</label><div class="input-with-icon"><Search :size="16"/><input :id="fieldId+'-search'" v-model="search" placeholder="Busque pelo nome"></div><p class="app-table-count">{{chosen.length}} de 8 selecionadas · {{tables.length}} {{tables.length===1?'disponível':'disponíveis'}}</p><div class="app-table-choices"><label v-for="table in filtered" :key="table.ref" class="app-table-option"><input v-model="chosen" type="checkbox" :value="table.ref" :disabled="chosen.length>=8&&!chosen.includes(table.ref)"><span>{{table.name}}<small>{{table.desk_name||table.ref}}</small></span></label><p v-if="!filtered.length">Nenhuma tabela corresponde à busca. Você pode continuar sem selecionar uma.</p></div><p v-if="filtered.length===100" class="app-table-count">Mostrando até 100 tabelas. Refine a busca pelo nome.</p></template><p v-if="tableError" class="form-error" role="alert">{{tableError}}</p></section></fieldset><p class="app-creation-scope"><ShieldCheck :size="17"/>A aplicação começa privada, sem gráficos. A publicação e a atualização dos dados serão conferidas durante a autoria.</p><p v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</p><button class="primary-button" :disabled="busy||(!prepared&&!valid)"><LoaderCircle v-if="busy" :size="16" class="spin"/><ShieldCheck v-else :size="16"/>{{prepared?'Conferir esta solicitação':'Preparar criação'}}</button></form></template>
 <template v-else><h3 ref="reviewHeading" tabindex="-1">{{status==='pending'?'Confira antes de criar':'Resultado da criação'}}</h3><template v-if="status==='pending'"><ApprovalReview :approval="review" :tenants="[{id:tenant,name:tenantName}]"/><div class="app-creation-buttons"><button class="secondary-button" :disabled="busy||uncertain" @click="decide('rejected')"><X :size="16"/>Recusar</button><button class="primary-button" :disabled="busy||uncertain" @click="decide('approved')"><LoaderCircle v-if="busy" :size="16" class="spin"/><Check v-else :size="16"/>Autorizar criação</button></div></template><div v-else-if="running" class="app-creation-progress" role="status"><LoaderCircle :size="23" class="spin"/><div><strong>{{status==='approved'?'Aguardando execução':'Criando no BI'}}</strong><p>Você pode fechar esta janela e acompanhar a operação em Atividade.</p></div><button class="icon-button" aria-label="Atualizar criação" :disabled="polling" @click="refreshStatus(true)"><RefreshCw :size="16"/></button></div><div v-else-if="confirmed" class="app-creation-success" role="status"><CheckCircle2 :size="25"/><div><h3>Seu ponto de partida está pronto</h3><p><strong>{{result.confirmed_name}}</strong> · Minha Mesa</p><p>{{result.app_creation.table_count}} {{result.app_creation.table_count===1?'tabela vinculada':'tabelas vinculadas'}}. Abra o projeto para pedir os indicadores e montar seus dashboards com a IA.</p><button class="primary-button" @click="emit('project',project!.id)">Continuar no projeto<ArrowRight :size="16"/></button></div></div><template v-else><p class="app-creation-scope" role="status">{{status==='rejected'?'Criação recusada. Nenhuma aplicação foi criada por esta revisão.':status==='expired'&&!review.payload?.app_creation_attempt?'Esta revisão expirou sem criar uma aplicação. Prepare outra quando quiser continuar.':review.payload?.execution?.message??'A criação ainda precisa de conferência. Consulte esta operação antes de criar outra aplicação.'}}</p><AppCreationRecovery :approval="review" :request="request" @confirmed="recovered"/></template><p v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</p><button v-if="uncertain" class="secondary-button" :disabled="polling" @click="refreshStatus(true)"><RefreshCw :size="16"/>Conferir solicitação</button></template>
</div></template>
<style scoped>
.app-creation-form fieldset{border:0;margin:0;padding:0;min-width:0}.app-creation-form label{display:block;font-size:12px;font-weight:600;color:#405979;margin:17px 0 8px}.app-creation-form label small{font-size:11px;color:#788ba4;font-weight:400;margin-left:6px}.app-creation-form input:not([type=checkbox]),.app-creation-form textarea{width:100%;background:#fff;border:1px solid #dce5f1;border-radius:8px;padding:11px 12px;color:#304c70;font-size:12px;line-height:1.7;outline:0}.app-creation-form input:not([type=checkbox]):focus,.app-creation-form textarea:focus{border-color:#8bb7f8;box-shadow:0 0 0 3px #0861ee0d}.app-source-choice .input-with-icon input{border:0;background:transparent;padding-left:38px;box-shadow:none}.app-creation-form textarea{min-height:90px;resize:vertical}.app-creation-form h3{font-size:15px;color:#2c4365;margin-bottom:12px}.app-creation-form h3:focus{outline:2px solid #1163e9;outline-offset:4px}.app-source-choice{margin:22px 0;padding:17px;border:1px solid #e0e8f3;border-radius:10px;background:#f8fbff}.app-source-choice>div:first-child{display:flex;gap:10px;color:#5780b3}.app-source-choice strong{font-size:12px;color:#365779}.app-source-choice p,.app-creation-progress p,.app-creation-success p{font-size:12px;line-height:1.8;color:#647b98;margin:7px 0 12px}.app-source-choice .secondary-button{margin-top:7px}.app-creation-form .app-table-option{display:flex;align-items:flex-start;gap:10px;padding:11px;margin:0;border-bottom:1px solid #e3eaf4;cursor:pointer}.app-table-option input{width:16px;height:16px;flex-shrink:0;margin-top:2px}.app-table-option span{min-width:0;overflow-wrap:anywhere;font-weight:500;line-height:1.7}.app-creation-form .app-table-option small{display:block;margin:2px 0 0;font-size:10px;color:#7a8da5}.app-table-choices{max-height:220px;overflow:auto;border:1px solid #dce6f3;border-radius:7px;background:#fff}.app-creation-scope{display:flex;align-items:flex-start;gap:9px;font-size:12px;line-height:1.8;color:#627b9b;padding:13px;background:#f4f8ff;border-radius:8px;margin:16px 0}.app-creation-scope>svg{flex-shrink:0;margin-top:3px}.app-creation-buttons{display:flex;gap:10px;flex-wrap:wrap}.app-creation-progress,.app-creation-success{display:flex;gap:13px;align-items:flex-start;padding:18px;background:#f7fbff;border:1px solid #dce7f5;border-radius:10px;color:#3971bd}.app-creation-progress>button{margin-left:auto}.app-creation-success{background:#f5fbf7;border-color:#cfe7da;color:#357b58}.app-creation-success>div{min-width:0}.app-creation-success h3{color:#2f684a}.app-creation-form .form-error{margin:12px 0}.app-creation-form button:focus-visible,.app-creation-form a:focus-visible{outline:2px solid #1163e9;outline-offset:3px}@media(max-width:600px){.app-source-choice{padding:13px}.app-creation-buttons button{flex:1}.app-creation-success,.app-creation-progress{padding:14px;gap:10px}}
</style>
